SELECT id, email, dept_id, salary, hire_date, is_remote, NTILE(3) OVER (PARTITION BY MONTH(hire_date) ORDER BY salary DESC, id) AS salary_bucket, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('YEAR', hire_date), manager_id ORDER BY hire_date, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date DESC, id) AS event_seq_2, CUME_DIST() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS salary_cume_dist, ROUND(salary / SUM(salary) OVER (PARTITION BY dept_id), 4) AS salary_share FROM employees;
